import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// Generic tiled GEMM: C(M,N) = sum_k A(M,K) * B(N,K)
// A is logically (M,K), B is logically (N,K) (i.e. contraction dim is
// the trailing mode for both operands), C is logically (M,N).
template <class TA, class TB, class TC, class SA, class SB, class SC>
__global__ static void
gemm_device(cute::Shape<int,int,int> shape_MNK,
            TA const* A, SA dA,
            TB const* B, SB dB,
            TC      * C, SC dC)
{
  using namespace cute;

  // Represent full tensors
  Tensor mA = make_tensor(make_gmem_ptr(A), make_shape(get<0>(shape_MNK), get<2>(shape_MNK)), dA); // (M,K)
  Tensor mB = make_tensor(make_gmem_ptr(B), make_shape(get<1>(shape_MNK), get<2>(shape_MNK)), dB); // (N,K)
  Tensor mC = make_tensor(make_gmem_ptr(C), make_shape(get<0>(shape_MNK), get<1>(shape_MNK)), dC); // (M,N)

  // Tile
  auto cta_tiler = make_shape(Int<128>{}, Int<128>{}, Int<8>{});
  auto cta_coord = make_coord(blockIdx.x, blockIdx.y, _);
  Tensor gA = local_tile(mA, cta_tiler, cta_coord, Step<_1,X,_1>{});
  Tensor gB = local_tile(mB, cta_tiler, cta_coord, Step<X,_1,_1>{});
  Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1,_1,X>{});

  // Shared memory
  __shared__ TA smemA[128*8];
  __shared__ TB smemB[128*8];
  Tensor sA = make_tensor(make_smem_ptr(smemA), make_shape(Int<128>{}, Int<8>{}));
  Tensor sB = make_tensor(make_smem_ptr(smemB), make_shape(Int<128>{}, Int<8>{}));

  // Thread layouts
  auto tA = make_layout(make_shape(Int<32>{}, Int<8>{}));
  auto tB = make_layout(make_shape(Int<32>{}, Int<8>{}));
  auto tC = make_layout(make_shape(Int<16>{}, Int<16>{}));

  Tensor tAgA = local_partition(gA, tA, threadIdx.x);
  Tensor tAsA = local_partition(sA, tA, threadIdx.x);
  Tensor tBgB = local_partition(gB, tB, threadIdx.x);
  Tensor tBsB = local_partition(sB, tB, threadIdx.x);

  Tensor tCsA = local_partition(sA, tC, threadIdx.x, Step<_1,X>{});
  Tensor tCsB = local_partition(sB, tC, threadIdx.x, Step<X,_1>{});
  Tensor tCgC = local_partition(gC, tC, threadIdx.x, Step<_1,_1>{});

  Tensor tCrC = make_tensor_like(tCgC);
  clear(tCrC);

  // Loop over K tiles
  int K_TILE_MAX = size<2>(tAgA);
  for (int k_tile = 0; k_tile < K_TILE_MAX; ++k_tile) {
    copy(tAgA(_,_,k_tile), tAsA);
    copy(tBgB(_,_,k_tile), tBsB);

    cp_async_fence();
    cp_async_wait<0>();
    __syncthreads();

    gemm(tCsA, tCsB, tCrC);
    __syncthreads();
  }

  // Epilogue
  axpby(1.0f, tCrC, 0.0f, tCgC);
}

torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim()==2 && B.dim()==2,  "A and B must be 2D");
  TORCH_CHECK(A.scalar_type()==at::kFloat && B.scalar_type()==at::kFloat,
              "Expect float32 tensors");

  int M = (int)A.size(0);
  int K = (int)A.size(1);
  int K2 = (int)B.size(0);
  int N = (int)B.size(1);
  TORCH_CHECK(K == K2, "Inner dimensions must match");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C   = torch::empty({M, N}, A.options());

  auto ptrA = A_c.data_ptr<float>();
  auto ptrB = B_c.data_ptr<float>();
  auto ptrC = C.data_ptr<float>();

  // A is (M,K) row-major: stride (K,1)
  auto dA = make_stride(K, Int<1>{});
  // B is (K,N) row-major, viewed as (N,K): stride (1,N)
  auto dB = make_stride(Int<1>{}, N);
  // C is (M,N) row-major: stride (N,1)
  auto dC = make_stride(N, Int<1>{});

  auto shape_MNK = make_shape(M, N, K);

  dim3 dimBlock(256);
  dim3 dimGrid((M + 127) / 128, (N + 127) / 128);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  gemm_device<<<dimGrid, dimBlock, 0, stream>>>(shape_MNK, ptrA, dA, ptrB, dB, ptrC, dC);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE gemm launch failed: ", cudaGetErrorString(err));

  return C;
}
"""

cute_matmul_ext = load_inline(
    name="cute_matmul_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["cute_matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include",
                          "/root/cutegen_test/cutegen/cutlass/include/cute/"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a single matrix multiplication (C = A * B)
    using a custom tiled CUTE GEMM kernel, optimized for the tall/skinny
    case where the contraction dimension K is small relative to M and N.
    """
    def __init__(self) -> None:
        super().__init__()
        self._ext = cute_matmul_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        A_c = A.contiguous().cuda().float() if not (A.is_cuda and A.dtype == torch.float32) else A
        B_c = B.contiguous().cuda().float() if not (B.is_cuda and B.dtype == torch.float32) else B
        return self._ext.cute_matmul(A_c, B_c)

